// Interval scheduling: minimum intervals to remove for non-overlap
function eraseOverlapIntervals(intervals) {
  if (!intervals.length) return 0;
  intervals.sort((a,b)=>a[1]-b[1]); // sort by END time
  let removed=0, lastEnd=-Infinity;
  for (const [start,end] of intervals) {
    if (start>=lastEnd) lastEnd=end;  // no overlap: select
    else removed++;                    // overlap: remove
  }
  return removed;
}

// Jump Game II: minimum jumps to reach end
function jump(nums) {
  let jumps=0, curReach=0, nextReach=0;
  for (let i=0;i<nums.length-1;i++) {
    nextReach=Math.max(nextReach, i+nums[i]);
    if (i===curReach) { jumps++; curReach=nextReach; }
  }
  return jumps;
}

// Gas station: find valid starting position
function canCompleteCircuit(gas, cost) {
  let total=0, curr=0, start=0;
  for (let i=0;i<gas.length;i++) {
    const delta=gas[i]-cost[i];
    total+=delta; curr+=delta;
    if (curr<0) { start=i+1; curr=0; } // reset start on deficit
  }
  return total>=0 ? start : -1;
}
